44:   subcmd: 'start' | 'abort' | 'approve' | 'complete'
45: ): { listCommand: string; subcommandCommand: string } {
46:   const args = client.argv.slice(2);
47:   const preservedParts: string[] = [];
48:   let hasNonInteractive = false;
49:   // args[0] = 'rolling-release', args[1] = subcmd
50:   for (let i = 2; i < args.length; i++) {
51:     const arg = args[i];
52:     if (arg === '--non-interactive') {
53:       hasNonInteractive = true;
54:       continue;
55:     }
56:     if (arg.startsWith('--cwd=')) {
57:       const cwdPath = arg.slice(6);
58:       if (cwdPath) {
59:         preservedParts.push('--cwd', cwdPath);
60:       }
61:       continue;
62:     }
63:     if (arg === '--cwd') {
64:       if (i + 1 < args.length) {
65:         preservedParts.push('--cwd', args[i + 1]);
66:         i++;
67:       }
68:       continue;
69:     }
70:     preservedParts.push(arg);
71:   }
72:   const preservedSuffix = preservedParts.join(' ');
73:   const listCommand = preservedSuffix
74:     ? `${packageName} ls ${preservedSuffix}`
75:     : `${packageName} ls`;
76:   const base = preservedSuffix
77:     ? `${packageName} rolling-release ${subcmd} ${preservedSuffix}`
78:     : `${packageName} rolling-release ${subcmd}`;
79:   const defaultSuffix =
